package com.fluxisai.proposal;
import java.math.BigDecimal; import java.time.*; import java.util.UUID; import jakarta.persistence.*;
@Entity @Table(name="proposals") public class Proposal {
 @Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id; @Column(name="user_id",nullable=false) private UUID userId; @Column(name="client_id",nullable=false) private UUID clientId; @Column(nullable=false,length=200) private String title; @Column(columnDefinition="text") private String description; @Column(nullable=false,length=3) private String currency; @Column(name="valid_until") private LocalDate validUntil; @Enumerated(EnumType.STRING) @Column(nullable=false,length=30) private ProposalStatus status; @Column(nullable=false,precision=19,scale=4) private BigDecimal subtotal; @Column(nullable=false,precision=19,scale=4) private BigDecimal total; @Column(name="created_at",nullable=false,updatable=false) private OffsetDateTime createdAt; @Column(name="updated_at",nullable=false) private OffsetDateTime updatedAt;
 protected Proposal(){} public Proposal(UUID u,UUID c,String t,String d,String cur,LocalDate v,ProposalStatus s){userId=u;clientId=c;title=t;description=d;currency=cur;validUntil=v;status=s==null?ProposalStatus.DRAFT:s;subtotal=BigDecimal.ZERO;total=BigDecimal.ZERO;} public void update(UUID c,String t,String d,String cur,LocalDate v,ProposalStatus s){clientId=c;title=t;description=d;currency=cur;validUntil=v;status=s==null?ProposalStatus.DRAFT:s;} public void totals(BigDecimal t){subtotal=t;total=t;} @PrePersist void create(){var n=OffsetDateTime.now(ZoneOffset.UTC);createdAt=n;updatedAt=n;} @PreUpdate void updateTime(){updatedAt=OffsetDateTime.now(ZoneOffset.UTC);}
 public UUID getId(){return id;} public UUID getUserId(){return userId;} public UUID getClientId(){return clientId;} public String getTitle(){return title;} public String getDescription(){return description;} public String getCurrency(){return currency;} public LocalDate getValidUntil(){return validUntil;} public ProposalStatus getStatus(){return status;} public BigDecimal getSubtotal(){return subtotal;} public BigDecimal getTotal(){return total;} public OffsetDateTime getCreatedAt(){return createdAt;} public OffsetDateTime getUpdatedAt(){return updatedAt;}
}
